import{_ as s,o as a,c as i,ag as e}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"SetCartDyn 设置笛卡尔动态特性","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetCartDyn.md","filePath":"3. 指令/5. 设置指令/SetCartDyn.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/SetCartDyn.md"};function r(h,t,l,d,o,k){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="setcartdyn-设置笛卡尔动态特性" tabindex="-1">SetCartDyn 设置笛卡尔动态特性 <a class="header-anchor" href="#setcartdyn-设置笛卡尔动态特性" aria-label="Permalink to &quot;SetCartDyn 设置笛卡尔动态特性&quot;">​</a></h1><p>该指令用于<strong>全局设置机器人笛卡尔空间（直线 <code>MovL</code>、圆弧 <code>MovC</code> 等）的动态特性参数</strong>。它不仅控制工具末端（TCP）的移动速度变化，还专门针对末端<strong>姿态（旋转）</strong> 的平滑度进行定义。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetCartDyn(Acc, Dec, Jerk, OriAcc, OriDec, OriJerk, Torq) SetCartDyn(加速度, 减速度, 加加速度, 姿态加速度, 姿态减速度, 姿态加加速度, 力矩)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Acc / Dec / Jerk：平移运动动态参数 (%)</td><td>int / INT 变量</td><td>控制 TCP 在直线或圆弧轨迹上的<strong>位移</strong>性能。数值越高，起停越快。</td><td></td></tr><tr><td>OriAcc / OriDec / OriJerk：姿态运动动态参数 (%)</td><td>int / INT 变量</td><td>专门控制末端工具<strong>旋转变换</strong>时的动态性能。例如在转弯处工具姿态发生剧烈变化时，调低这些值可以使旋转动作更柔和。</td><td></td></tr><tr><td>Torq：力矩 (%)</td><td>int / INT 变量</td><td>限制所有关节电机的最大输出扭矩。</td><td>取值范围：<strong>1-100</strong>。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p><code>SetCartDyn</code> 作用于<strong>笛卡尔空间</strong>的运动。与关节空间不同，它通过协调多个关节的输出，确保工具末端在直线上运行时，其速度和姿态的变化符合设定的百分比限制。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetCartDyn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>向 <strong>P1</strong> 点进行直线运动时：</p><ol><li><strong>平移部分</strong>：以 80% 的动态响应进行加速和刹车。</li><li><strong>姿态部分</strong>：如果 P1 点的姿态与起点不同，旋转过程将以较慢的 <strong>50%</strong> 动态响应运行，以减少末端工具的晃动。</li><li><strong>力矩限制</strong>：电机力矩上限限制在 <strong>60%</strong>。</li></ol><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>窄空间避障</strong>：在狭窄空间内进行直线运动时，通过降低 <code>OriAcc</code> 等参数，防止工具姿态快速切换时由于惯性导致的碰撞。</li><li><strong>精密涂胶/切割</strong>：在轨迹转折处，通过优化 <code>Jerk</code> 和 <code>OriJerk</code>，确保 TCP 的运行轨迹更加圆滑，减少物理震动对工艺质量的影响。</li><li><strong>柔性装配</strong>：在插拔或装配任务中，调低 <code>Torq</code> 以实现简单的力限制保护。</li></ul>`,19)])])}const g=s(n,[["render",r]]);export{c as __pageData,g as default};
